typedef float vm_num_t;

class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
    void *my_thread;

    char *get_SP() const { return SP; }
    void pop(int n) { SP -= n; }
    bool push(const char *src, int n);
};

template<class T>
class vector {
public:
    typedef T *iterator;

private:
    iterator start;
    iterator finish;
    iterator end_of_storage;

public:
    iterator end() { return finish; }
};

typedef vector<vm_num_t> num_list;
typedef num_list *vm_num_list_t;
typedef num_list::iterator vm_num_list_iterator_t;

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    protected:
        char *name;
    public:
        virtual ~function();
        virtual bool operator()(vm_stack &stack, entry_t entry) { return true; }
    };
};

class slf_num_list_end_t : public script_library_class::function
  {
  public:
    struct parms_t
      {
      vm_num_list_t me;
      };
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      stack.pop(sizeof(parms_t));
      parms_t* parms = (parms_t*)stack.get_SP();
      vm_num_list_iterator_t result = parms->me->end();
      if (!stack.push((char*)&result,sizeof(result)) )
        ;
      return true;
      }
  };
